-- Custom order queries
-- Create/Get/Delete are auto-generated by pgtempl (CreateDefaultOrder / GetOrder / DeleteOrder).

-- name: ListSellerOrders :many
SELECT * FROM "order"."order"
WHERE "seller_id" = @seller_id
ORDER BY "date_created" DESC
LIMIT @limit_count::INTEGER OFFSET @offset_count::INTEGER;

-- name: ListCountSellerOrder :many
SELECT sqlc.embed(embed_order), COUNT(*) OVER() as total_count
FROM "order"."order" embed_order
WHERE embed_order."seller_id" = @seller_id
    AND (embed_order."id"::text ILIKE '%' || sqlc.narg('search')::text || '%' OR sqlc.narg('search') IS NULL)
ORDER BY embed_order."date_created" DESC
LIMIT sqlc.narg('limit')::int
OFFSET sqlc.narg('offset')::int;

-- name: HasPurchasedSku :one
SELECT EXISTS(
    SELECT 1 FROM "order".item i
    WHERE i.account_id = @account_id
      AND i.order_id IS NOT NULL
      AND i.date_cancelled IS NULL
      AND i.sku_id = ANY(@sku_ids::UUID[])
) AS has_purchased;

-- name: ListSuccessOrdersBySkus :many
SELECT DISTINCT o.* FROM "order"."order" o
JOIN "order".item i ON i.order_id = o.id
WHERE o.buyer_id = @buyer_id
  AND i.sku_id = ANY(@sku_ids::UUID[])
  AND i.date_cancelled IS NULL
ORDER BY o.date_created DESC;

-- name: ValidateOrderForReview :one
SELECT EXISTS(
    SELECT 1 FROM "order"."order" o
    JOIN "order".item i ON i.order_id = o.id
    WHERE o.id = @order_id
      AND o.buyer_id = @buyer_id
      AND i.sku_id = ANY(@sku_ids::UUID[])
      AND i.date_cancelled IS NULL
) AS is_valid;

-- name: GetOrderByTransportID :one
SELECT o.* FROM "order"."order" o
WHERE o.transport_id = @transport_id;

-- CreateOrderIdempotent inserts the order row with a caller-chosen ID (the
-- fulfillment workflow key). ON CONFLICT DO NOTHING makes the durable-Run
-- retry after a crash-after-commit a no-op instead of a duplicate-key wedge.
-- name: CreateOrderIdempotent :exec
INSERT INTO "order"."order" ("id", "buyer_id", "seller_id", "transport_id", "address", "date_created", "confirmed_by_id", "confirm_session_id", "note")
VALUES (@id, @buyer_id, @seller_id, @transport_id, @address, @date_created, @confirmed_by_id, @confirm_session_id, @note)
ON CONFLICT ("id") DO NOTHING;